                self._pipe.run_update(self.core.elements, self.core.primitives, self.core.header, obs_like, feedback or {})
            else:
                self._pipe.run(self.core.elements, self.core.primitives, self.core.header, obs_like, feedback or {})
        except Exception:
            pass

