from typing import Dict, Any, List, Tuple
from dataclasses import dataclass

def _kgrams(seq: Tuple, k: int) -> List[Tuple]:
    out = []
    n = len(seq)
    for i in range(0, max(0, n - k + 1)):
        out.append(tuple(seq[i:i + k]))
    return out

@dataclass
class EI_ChangeOps:
    k: int = 3

